import { Component, input } from '@angular/core';

/**
 * A grade's line of the summary: how many people not retired are on it today, their due-totals added up, and how many
 * of them are active.
 */
export interface GradeSummary {
  grade: string;
  count: number;
  dueTotal: string;
  active: number;
}

/**
 * A period's line of the summary: its due-total as the period list shows it, and its change from the period before it
 * by start date (blank for the earliest).
 */
export interface PeriodSummary {
  name: string;
  dueTotal: string;
  change: string;
}

/** A status's line of the summary: how many of the sheet's claims have it. */
export interface StatusSummary {
  status: string;
  count: number;
}

/** A void reason's line of the summary: how many VOID claims were voided with it. */
export interface VoidReasonSummary {
  reason: string;
  count: number;
}

// The sheet at a glance: figures per grade, per period, per claim status and per void reason, each agreeing with the lists.
@Component({
  selector: 'app-summary',
  template: `
    <section aria-labelledby="summary-heading">
      <h2 id="summary-heading">Summary</h2>
      <table>
        <caption>By grade (retired people excluded)</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">People</th><th scope="col">Due total</th><th scope="col">Active</th></tr>
        </thead>
        <tbody>
          @for (g of grades(); track g.grade) {
            <tr>
              <th scope="row">{{ g.grade }}</th>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-count'">{{ g.count }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-due-total'">{{ g.dueTotal }}</td>
              <td [attr.data-testid]="'summary-grade-' + g.grade + '-active'">{{ g.active }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By period</caption>
        <thead>
          <tr><th scope="col">Period</th><th scope="col">Due total</th><th scope="col">Change</th></tr>
        </thead>
        <tbody>
          @for (p of periods(); track p.name) {
            <tr>
              <th scope="row">{{ p.name }}</th>
              <td [attr.data-testid]="'summary-period-' + p.name + '-due-total'">{{ p.dueTotal }}</td>
              <td [attr.data-testid]="'summary-period-' + p.name + '-change'">{{ p.change }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>By claim status</caption>
        <thead>
          <tr><th scope="col">Status</th><th scope="col">Claims</th></tr>
        </thead>
        <tbody>
          @for (s of statuses(); track s.status) {
            <tr>
              <th scope="row">{{ s.status }}</th>
              <td [attr.data-testid]="'summary-status-' + s.status + '-count'">{{ s.count }}</td>
            </tr>
          }
        </tbody>
      </table>
      @if (voidReasons().length > 0) {
        <table>
          <caption>By void reason</caption>
          <thead>
            <tr><th scope="col">Void reason</th><th scope="col">Voided claims</th></tr>
          </thead>
          <tbody>
            @for (v of voidReasons(); track v.reason) {
              <tr>
                <th scope="row">{{ v.reason }}</th>
                <td [attr.data-testid]="'summary-void-' + v.reason + '-count'">{{ v.count }}</td>
              </tr>
            }
          </tbody>
        </table>
      }
    </section>
  `,
})
export class Summary {
  readonly grades = input.required<GradeSummary[]>();
  readonly periods = input.required<PeriodSummary[]>();
  readonly statuses = input.required<StatusSummary[]>();
  readonly voidReasons = input<VoidReasonSummary[]>([]);
}
import { Component, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { AuditViewer } from '../audit-viewer/audit-viewer';
import { Holidays } from '../holidays/holidays';
import { People } from '../people/people';
import { Settings } from '../settings/settings';
import { TemplatesList } from '../templates/templates';
import { VoidReasonsList } from '../void-reasons/void-reasons';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [AuditViewer, Holidays, People, Settings, TemplatesList, VoidReasonsList],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
      <form (submit)="load($event)">
        <label for="sheet-id">Sheet id</label>
        <input
          id="sheet-id"
          data-testid="sheet-id-input"
          [value]="sheetId()"
          (input)="sheetId.set(value($event)); sheetError.set(null)"
        />
        <button type="submit" data-testid="sheet-load">Load</button>
        @if (sheetError(); as error) {
          <p role="alert" data-testid="sheet-error">{{ error }}</p>
        }
      </form>
      @if (session.sheet(); as sheet) {
        <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
        <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
        <form (submit)="saveToday($event)">
          <label for="sheet-today-input">Change today</label>
          <input
            id="sheet-today-input"
            type="date"
            data-testid="sheet-today-input"
            [value]="todayInput()"
            (input)="todayInput.set(value($event)); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-today-save">Set today</button>
        </form>
        <form (submit)="setAsOf($event)">
          <label for="asof-date">Show as of</label>
          <input
            id="asof-date"
            type="date"
            data-testid="asof-date"
            [value]="asOfInput()"
            (input)="asOfInput.set(value($event)); asOfError.set(null)"
          />
          <button type="submit" data-testid="asof-set">Set as of</button>
          <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as error) {
            <p role="alert" data-testid="asof-error">{{ error }}</p>
          }
        </form>
        <p>As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
        <p>Parent sheet <strong data-testid="sheet-parent">{{ session.parent() ?? '' }}</strong></p>
        <p>Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong></p>
        <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
        <form (submit)="cloneSheet($event)">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input
            id="sheet-clone-to"
            data-testid="sheet-clone-to"
            [value]="cloneTo()"
            (input)="cloneTo.set(value($event)); sheetError.set(null)"
          />
          <button type="submit" data-testid="sheet-clone">Clone sheet</button>
        </form>
        <p>Cloned to <strong data-testid="sheet-cloned-to">{{ clonedTo() ?? '' }}</strong></p>
        <app-settings />
        <app-holidays />
        <app-void-reasons />
        <app-templates />
        <app-people />
        <app-audit-viewer />
      }

